  const names = {phone:'通话',browser:'浏览器',music:'音乐',settings:'设置',calendar:'日历',weather:'天气',clock:'时钟',mail:'邮件',map:'地图',wechat:'微信',qq:'QQ',redbook:'小红书',weibo:'微博'};
