  const profileDefaults=k=>({name:k==='weibo'?'星河':'海风来信',avatar:'',cover:'',gender:'女',ip:'浙江',vip:'VIP',summary:'昨日阅读 128　互动 36',bio:k==='weibo'?'记录日常，也收藏每一次抬头看见的星光。':'在海边生活｜摄影与日常\n把喜欢的风景，慢慢分享给你。',handle:k==='weibo'?'xinghe_0412':'haifeng_1021',location:'浙江 杭州',following:'128',followers:k==='weibo'?'2.6万':'1.2万',likes:k==='weibo'?'8.9万':'3.8万'});
