    browser:{pages:[{id:K.id(),title:'海边书店',url:'https://book.example',text:'今日书单\n在这里收藏你的故事。'}]},
    music:{tracks:[{id:K.id(),title:'海风',artist:'故事音乐人',cover:'',audio:''}]},
