    const text=(v,max=20000)=>{if(typeof v!=='string'||v.length>max)fail('文本格式或长度');return v;};
    const bool=v=>{if(typeof v!=='boolean')fail('开关必须为布尔值');return v;};
    const num=(v,min,max)=>{if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max)fail('数值范围 '+min+'–'+max);return v;};
    const image=v=>{text(v,K.MAX_IMAGE);if(v&&!/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+={0,2}$/.test(v))fail('仅支持内嵌图片');return v;};
    const ids=new Set([...result.contacts,...result.photos,...result.notes,...result.notifications,...result.contacts.flatMap(c=>c.messages)].map(x=>x.id));
    const uid=v=>{text(v,100);if(!/^[\w-]+$/.test(v)||ids.has(v))fail('ID 无效或重复');ids.add(v);return v;};
    const list=(v,fn)=>{if(!Array.isArray(v)||v.length>200)fail('列表最多200项');return v.map(x=>fn(obj(x,'列表项')));};
    const date=v=>{text(v,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v))||new Date(v).toISOString().slice(0,10)!==v)fail('日期');return v;};
    const time=v=>{text(v,5);if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))fail('时间 HH:MM');return v;};
