    const out={apps:{},widgets:{},accounts:{}};
    const desktop=s.desktop===undefined?f.desktop:obj(s.desktop,'desktop');
    const keys=(v,max,label)=>{if(!Array.isArray(v)||v.length>max||v.some(k=>typeof k!=='string'||!Object.hasOwn(allNames,k))||new Set(v).size!==v.length)fail(label);return [...v];};
    out.desktop={dock:keys(desktop.dock,4,'Dock 最多4个且不能重复'),order:keys(desktop.order,20,'桌面排序无效')};
    if(JSON.stringify(out.desktop.dock)===JSON.stringify(['wechat','qq','mail','map']))out.desktop.dock=[...f.desktop.dock];
    const phone=obj(s.phone||f.phone,'phone');
    out.phone={connectDelay:phone.connectDelay===undefined?1:num(phone.connectDelay,0,60),defaultInterval:phone.defaultInterval===undefined?2:num(phone.defaultInterval,0.1,300),records:list(phone.records,x=>({id:uid(x.id),name:text(x.name,80),number:text(x.number,80),avatar:image(x.avatar??''),time:text(x.time??'',80),history:list(ensureHistory(x,result.phone),h=>({id:uid(h.id),date:date(h.date),time:time(h.time),missed:bool(h.missed),unread:bool(h.unread)})),text:text(x.text??''),missed:bool(x.missed??false),unread:bool(x.unread??false),script:x.script===undefined?[]:list(x.script,line=>({id:uid(line.id),speaker:text(line.speaker,80),text:text(line.text),interval:line.interval===undefined||line.interval===null?null:num(line.interval,0.1,300)})),connectDelay:x.connectDelay==null?null:num(x.connectDelay,0,60),lineInterval:x.lineInterval==null?null:num(x.lineInterval,0.1,300)}))};
    out.browser={pages:list((s.browser||f.browser).pages,x=>({id:uid(x.id),title:text(x.title,200),url:text(x.url,200),text:text(x.text)}))};
    out.music={tracks:list((s.music||f.music).tracks,x=>{const audio=text(x.audio,K.MAX_JSON);if(audio&&!/^data:audio\/(mpeg|mp3|wav|x-wav|ogg|mp4|webm);base64,[A-Za-z0-9+/]+={0,2}$/.test(audio))fail('音频格式无效');return {id:uid(x.id),title:text(x.title,200),artist:text(x.artist,200),cover:image(x.cover),audio};})};
    out.desktop.order.push(...Object.keys(allNames).filter(k=>!out.desktop.order.includes(k)));
    for(const k of Object.keys(names))out.apps[k]=obj(s.apps,'apps')[k]===undefined?true:bool(s.apps[k]);
    for(const k of ['calendar','weather'])out.widgets[k]=bool(obj(s.widgets,'widgets')[k]);
    for(const k of social){const a=obj(obj(s.accounts,'accounts')[k],'账号');out.accounts[k]={name:text(a.name,80),avatar:image(a.avatar)};}
    const group=k=>obj(s[k],k);
    out.calendar={events:list(group('calendar').events,x=>({id:uid(x.id),title:text(x.title,200),date:date(x.date),time:time(x.time),text:text(x.text)}))};
    out.weather={};for(const k of ['city','temperature','condition','low','high','detail'])out.weather[k]=text(group('weather')[k],200);
    out.clock={alarms:list(group('clock').alarms,x=>({id:uid(x.id),time:time(x.time),label:text(x.label,200),enabled:bool(x.enabled)}))};
    out.mail={items:list(group('mail').items,x=>({id:uid(x.id),title:text(x.title,200),from:text(x.from,200),time:text(x.time,80),text:text(x.text)}))};
    out.map={image:image(group('map').image),places:list(group('map').places,x=>({id:uid(x.id),name:text(x.name,200),x:num(x.x,0,100),y:num(x.y,0,100),text:text(x.text)}))};
    for(const k of ['redbook','weibo']){
      const g=group(k),p=g.profile===undefined?profileDefaults(k):obj(g.profile,'个人主页');
      out[k]={profile:{},posts:list(g.posts,x=>{
        const images=x.images===undefined?[]:x.images;if(!Array.isArray(images)||images.length>9)fail('帖子最多9张补充图片');
        const body=text(x.text),topics=text(x.topics??'',2000);
        const merged=k==='weibo'&&topics&&!body.includes(topics)?body+(body?'\n':'')+topics:body;
        return {id:uid(x.id),title:text(x.title,200),text:text(merged),image:image(x.image),images:images.map(image),avatar:image(x.avatar??''),time:text(x.time,80),author:text(x.author??'',80),likes:text(x.likes??'128',40),comments:text(x.comments??'16',40),reposts:text(x.reposts??'8',40),saves:text(x.saves??'32',40),source:text(x.source??'iPhone',200),topics:k==='weibo'?'':topics,quoteAuthor:text(x.quoteAuthor??'',200),quoteText:text(x.quoteText??'',20000)};
      })};
      for(const field of ['name','bio','handle','location','following','followers','likes','gender','ip','vip','summary'])out[k].profile[field]=text(p[field]??profileDefaults(k)[field],field==='bio'?2000:200);
      out[k].profile.avatar=image(p.avatar);
      out[k].profile.cover=image(p.cover??'');
    }
    out.storyEvents=list(s.storyEvents??[],x=>{
      const branches={};for(const key of ['answer','end','reject','timeout'])branches[key]=list(obj(x.branches,'事件分支')[key]??[],a=>{
        const speaker=a.speaker??'left';if(!['left','right'].includes(speaker))fail('事件消息方向');
        const source=raw.contacts.find(c=>c.id===a.contact),app=messageApps.includes(source?.app)?source.app:'sms';
        const targetApp=source?app:(a.targetApp??'sms');if(!messageApps.includes(targetApp))fail('目标软件');
        const targetType=a.targetType??'direct';if(targetType!=='direct')fail('暂不支持的会话类型');
        return {id:uid(a.id),contact:text(a.contact,100),targetApp,targetType,delay:num(a.delay,0,86400),speaker,text:text(a.text)};
      });
      const direction=x.direction??'incoming',result=x.result??'answer';
      if(!['incoming','outgoing'].includes(direction))fail('通话方向');
      if(!['answer','noAnswer','rejected'].includes(result))fail('呼出结果');
      ensureEventLines({extra:{phone:out.phone}},x);
      if(!Array.isArray(x.speakers)||x.speakers.length>200)fail('说话人列表');
      const speakers=x.speakers.map(v=>text(v,80));
      return {speakers,id:uid(x.id),direction,result,wait:num(x.wait??1,0.1,86400),enabled:bool(x.enabled),title:text(x.title,200),record:text(x.record,100),lines:list(x.lines??out.phone.records.find(r=>r.id===x.record)?.script.map(line=>({...line,id:K.id()}))??[],line=>({id:uid(line.id),speaker:text(line.speaker,80),text:text(line.text),interval:line.interval==null?null:num(line.interval,0.1,300)})),connectDelay:x.connectDelay==null?null:num(x.connectDelay,0,60),lineInterval:x.lineInterval==null?null:num(x.lineInterval,0.1,300),delay:num(x.delay,0,86400),timeout:num(x.timeout??30,0.1,86400),retry:bool(x.retry),retryDelay:x.retryDelay==null?null:num(x.retryDelay,0.1,86400),branches};
    });
