  const add=(path,kind)=>`<button class="button" data-action="extra-add" data-path="${path}" data-kind="${kind}">添加条目</button>`;
  const collection=(title,path,kind,items,fields)=>`<div class="section-heading"><h2>${title}</h2>${add(path,kind)}</div>${items.map((x,i)=>`<div class="card" data-editor-item="${E(x.id)}"><div class="item-heading"><strong>${title} ${i+1}</strong><button class="button" data-action="extra-delete" data-path="${path}" data-index="${i}">删除</button></div><div class="field-grid">${fields(x,path+'.'+i)}</div></div>`).join('')}`;
  const desktopEditor=s=>`<div class="card"><h2>桌面与 Dock</h2><p class="help">Dock 最多4个；禁用应用自动隐藏。Dock 中应用不重复出现在桌面。拖动排序的替代操作：上移 / 下移。每页8个应用，四列。</p>${['dock','order'].map(group=>`<h3>${group==='dock'?'Dock 快捷应用':'桌面排序'}</h3>${s.desktop[group].map((k,i)=>`<div class="item-heading desktop-editor-row"><span>${E(allNames[k])}</span><span class="desktop-editor-actions">${group==='order'&&Object.hasOwn(s.apps,k)?control('启用','extra.apps.'+k,s.apps[k],'checkbox','启用'+allNames[k]+'应用'):''}<button class="button" data-action="extra-desktop-up" data-group="${group}" data-index="${i}" ${i===0?'disabled':''}>上移</button><button class="button" data-action="extra-desktop-down" data-group="${group}" data-index="${i}" ${i===s.desktop[group].length-1?'disabled':''}>下移</button>${group==='dock'?`<button class="button" data-action="extra-desktop-remove" data-group="dock" data-index="${i}">移除</button>`:''}</span></div>`).join('')}`).join('')}${s.desktop.dock.length<4?`<div class="field-grid">${Object.keys(allNames).filter(k=>!s.desktop.dock.includes(k)).map(k=>`<button class="button" data-action="extra-desktop-add" data-app="${k}">加入 ${E(allNames[k])}</button>`).join('')}</div>`:''}</div>`;
  const targetAppOf=c=>messageApps.includes(c?.app)?c.app:'sms';
