      if(nav.screen==='map')body=toolbar('地图','home')+`<div class="ps-scroll"><div class="ps-map">${s.map.image?`<img src="${E(s.map.image)}" alt="离线静态地图">`:''}${s.map.places.map(x=>`<button class="ps-map-pin" data-act="place" data-id="${E(x.id)}" style="left:${x.x}%;top:${x.y}%">● ${E(x.name)}</button>`).join('')}</div>${s.map.places.map(x=>row(x.name,x.text,'place',x.id)).join('')}<div class="ps-offline">静态底图 · 无定位与导航</div></div>`;
      if(nav.screen==='place'){const x=s.map.places.find(x=>x.id===nav.id);body=toolbar('地点详情','map')+`<div class="ps-scroll ps-rich"><h2>${E(x?.name||'地点已删除')}</h2><p>${E(x?.text||'')}</p></div>`;}
      const socialSvg=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({back:'<path d="m15 5-7 7 7 7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',down:'<path d="m6 9 6 6 6-6"/>',repost:'<path d="M14 3h7v7M21 3l-12 12M10 5H4v15h15v-6"/>',comment:'<path d="M4 4h16v13H9l-5 4V4Z"/>',like:'<path d="M8 21H3V10h5m0 11h10l3-11h-7l1-6c0-2-3-2-3 0l-4 6v11Z"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3ZM10 21h4"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3M16 14l2 2 4-4"/>'})[name]||''}</svg>`;
      if(['redbook','weibo','redbook-detail','weibo-detail'].includes(nav.screen)){
        const app=nav.screen.split('-')[0],p={...profileDefaults(app),...s[app].profile},red=app==='redbook';
        const inert=(label,cls='')=>`<button type="button" class="${cls}" data-social-static>${label}</button>`;
        const pics=x=>[x.image,...(x.images||[])].filter(Boolean);
        // Escape every text segment independently: entities and markup cannot become tokens/HTML.
        const tokens=value=>String(value).split(/([#@][^\s]+)/u).map((part,i)=>i%2?`<span class="social-token">${E(part)}</span>`:E(part)).join('');
        const images=x=>`<div class="social-images ${pics(x).length===1?'single':''}">${pics(x).map(src=>`<img data-social-static src="${E(src)}" alt="${E(x.title)}">`).join('')}</div>`;
        const vipBadge=()=>{const label=String(p.vip||'').trim();if(!label)return '';const units=Array.from(label).reduce((n,c)=>n+(/[^\x00-\xff]/.test(c)?1.7:1),0),w=Math.min(100,Math.max(42,18+units*6));return `<span class="social-vip" title="${E(label)}"><svg role="img" aria-label="${E(label)}" viewBox="0 0 ${w} 16" style="width:${w/3.93}cqw;height:4.07cqw"><path fill="#d6a34a" d="M8 3H${w}l-4 6 2 5H8Z"/><path fill="#f6d78a" d="m1 3 4 3 4-5 4 5 4-3-2 10H3Z"/><path fill="#a97828" d="M4 14h10v2H4Z"/><text x="18" y="11.8" fill="#69451d" font-family="Arial,sans-serif" font-size="9" font-weight="700" textLength="${w-22}" lengthAdjust="spacingAndGlyphs">${E(label)}</text></svg></span>`;};
        const badges=()=>{const g=K.extensions.gender(p.gender);return `${g?`<svg class="social-gender-icon" role="img" aria-label="${g}" viewBox="0 0 24 24"><circle cx="12" cy="12" r="12" fill="${g==='男'?'#439de8':'#ee7fab'}"/><g fill="none" stroke="white" stroke-width="1.8" stroke-linecap="round"><circle cx="${g==='男'?10:12}" cy="${g==='男'?14:9}" r="4"/>${g==='男'?'<path d="m13 11 5-5m-5 0h5v5"/>':'<path d="M12 13v6m-3-3h6"/>'}</g></svg>`:''}${vipBadge()}`;};
        const author=x=>`<div class="ps-feed-author">${avatar(red?(x.author||p.name):p.name,red?(x.avatar||p.avatar):p.avatar)}<span class="ps-feed-author-copy"><span class="weibo-author-line"><strong class="${!red&&String(p.vip||'').trim()?'has-vip':''}">${E(red?(x.author||p.name):p.name)}</strong>${red?'':vipBadge()}</span>${red?`<small>${E(x.time)}　来自 ${E(x.source||'iPhone')}</small>`:`<span class="weibo-author-meta">${E(x.time)}　来自 ${E(x.source||'iPhone')}</span>`}</span>${inert(socialSvg('down'))}</div>`;
        const stats=x=>`<div class="ps-profile-post-stats">${[['repost',x.reposts??'8'],['comment',x.comments??'16'],['like',x.likes??'128']].map(([icon,count])=>inert(socialSvg(icon)+`<span>${E(count)}</span>`)).join('')}</div>`;
        const top=`<header class="social-top"><button data-act="home" aria-label="返回桌面">${socialSvg('back')}</button>${red?'<span></span>':`<strong class="weibo-compact-name">${E(p.name)}</strong>${inert(socialSvg('search'))}`}${inert(socialSvg('more'))}</header>`;
        const cover=p.cover?`<img class="social-cover-image" src="${E(p.cover)}" alt="主页封面">`:'';
        const identity=`<div class="ps-profile-identity">${avatar(p.name,p.avatar)}<div><h1>${E(p.name)}</h1><small>${red?'小红书号：'+E(p.handle)+'<br>IP属地：'+E(p.ip||p.location):badges()}</small></div></div>`;
        const numbers=`<div class="ps-profile-stats"><span><b>${E(red?p.following:p.followers)}</b>${red?'关注':'粉丝'}</span><span><b>${E(red?p.followers:p.following)}</b>${red?'粉丝':'关注'}</span><span><b>${E(p.likes)}</b>${red?'获赞与收藏':'转评赞'}</span></div>`;
        const head=`<div class="ps-profile-cover ${app}" data-edit="profile">${cover}${red?'':'<div class="weibo-cover-space"></div>'}${identity}${numbers}${red?'':inert(E(p.summary),'social-summary')}<p class="ps-profile-bio">${red?E(p.bio):`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3H5v18h14V8l-5-5Z"/><path d="M14 3v5h5M8 12h8M8 16h6"/></svg><span>${E(p.bio)}</span>`}</p>${red?`<small class="social-gender">${E(p.gender)}</small><div class="social-actions">${inert('关注','red-follow')}${inert('发私信')}${inert('♙＋')}</div>`:''}</div>`;
        const posts=s[app].posts.map(x=>red?`<article class="ps-red-card" data-post-id="${E(x.id)}" data-act="redbook-detail" data-id="${E(x.id)}" tabindex="0" role="button">${pics(x)[0]?`<img src="${E(pics(x)[0])}" alt="${E(x.title)}">`:`<div class="ps-text-cover">${E(x.title)}<p>${E(x.text.slice(0,80))}</p></div>`}<strong>${E(x.title)}</strong><div class="ps-red-author">${avatar(x.author||p.name,x.avatar||p.avatar)}<small>${E(x.author||p.name)}<br>${E(x.time)}</small><small>♡ ${E(x.likes??'128')}</small></div></article>`:`<article class="ps-weibo-card" data-post-id="${E(x.id)}">${author(x)}<div class="ps-profile-post"><p>${tokens(x.text.trim()?x.text:x.title)}</p>${x.quoteAuthor||x.quoteText?`<div class="social-quote"><b>@${E(x.quoteAuthor||'原作者')}</b><p>${tokens(x.quoteText||'')}</p>${images(x)}</div>`:images(x)}</div>${stats(x)}</article>`).join('');
        const categories=red?`<div class="social-notes-heading"><strong>笔记</strong>${inert('⌕')}</div>`:`<nav class="social-categories">${['动态','微博','视频','超话','相册'].map(t=>inert(t,t==='微博'?'selected':'')).join('')}</nav><div class="social-filter">${inert('全部微博 ('+s[app].posts.length+')　⌄')}${inert('筛选 ☷')}</div>`;
        body=`<section class="ps-brand-shell social-dark ${app}">${red?'':top}<div class="ps-scroll social-scroll">${red?top:''}${head}<section class="social-posts">${categories}<div class="${red?'ps-waterfall':'ps-weibo-feed'}">${posts||'<div class="ps-empty">还没有发布内容</div>'}</div></section></div>${red?'':`<nav class="social-bottom">${[['comment','留言'],['bell','通知'],['star','推荐'],['user','已关注']].map(([icon,t])=>inert(socialSvg(icon)+`<span>${t}</span>`)).join('')}</nav>`}</section>`;
        if(red&&nav.screen==='redbook-detail'){
          const x=s.redbook.posts.find(x=>x.id===nav.id);
          body=`<section class="ps-brand-shell social-dark redbook social-detail"><header class="social-top"><button data-act="redbook" aria-label="返回小红书主页">‹</button>${avatar(x?.author||p.name,x?.avatar||p.avatar)}<strong>${E(x?.author||p.name)}</strong>${inert('关注','detail-follow')}${inert('↗')}</header>${x?`<div class="ps-scroll"><article data-edit="post" data-post-id="${E(x.id)}"><div class="social-detail-images">${pics(x).map(src=>`<img src="${E(src)}" alt="${E(x.title)}">`).join('')}</div><div class="social-dots">${pics(x).map((_,i)=>`<span class="${i===0?'selected':''}">•</span>`).join('')}</div><div class="ps-profile-post"><h2>${E(x.title)}</h2><p>${E(x.text)}</p><p class="social-topics">${E(x.topics||'')}</p><small>${E(x.time)} · ${E(p.ip||p.location)}</small></div></article></div><footer class="social-detail-bottom">${inert('说点什么','social-comment')}${inert('♡ '+E(x.likes??'128'))}${inert('☆ '+E(x.saves??'32'))}${inert('☏ '+E(x.comments??'16'))}</footer>`:'<div class="ps-empty">帖子已删除</div>'}</section>`;
        }
      }
      if(nav.screen==='incoming'&&incoming){const x=incoming.record;body=`<section class="ps-call ps-incoming"><div class="ps-call-identity">${avatar(x.name,x.avatar)}<h1>${E(x.name||x.number)}</h1><p>手机</p></div><div class="ps-incoming-space"></div><div class="ps-incoming-static"><span>${callArt('bell')}提醒我</span><span>${callArt('message')}信息</span></div>${incoming.locked?`<div class="ps-answer-slider" role="slider" tabindex="0" aria-label="滑动来接听" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0" aria-valuetext="向右滑动接听" ${editing?'aria-disabled="true"':''}><span>滑动来接听</span><b data-answer-thumb>${callArt('answer')}</b></div>`:`<div class="ps-incoming-actions"><button data-act="incoming-reject"><b>${callArt('end')}</b><span>拒绝</span></button><button data-act="incoming-answer"><b>${callArt('answer')}</b><span>接听</span></button></div>`}</section>`;}
      if(nav.screen==='settings')body=toolbar('设置','home')+`<div class="ps-scroll ps-rich"><h2>显示与锁屏</h2><label>时间来源 <select data-phone-setting="useSystemTime"><option value="true" ${data.phone.useSystemTime?'selected':''}>本机时间</option><option value="false" ${!data.phone.useSystemTime?'selected':''}>剧情时间</option></select></label><p>剧情时间从设定的 ${E(data.phone.time)} 开始走时；重置剧情重新起算。</p><label>自动锁屏 <select data-phone-setting="autoLock">${[[0,'永不'],[30,'30秒'],[60,'1分钟'],[120,'2分钟'],[300,'5分钟']].map(([v,l])=>`<option value="${v}" ${data.phone.autoLock===v?'selected':''}>${l}</option>`).join('')}</select></label></div>`;
      const phoneSvg=key=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({speaker:'<path d="M3 9h4l5-4v14l-5-4H3ZM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14"/>',video:'<rect x="3" y="6" width="12" height="12" rx="3"/><path d="m15 10 6-4v12l-6-4"/>',mute:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',add:'<path d="M12 4v16M4 12h16"/>',end:'<path d="M3 16v-5c5-5 13-5 18 0v5h-5v-4a12 12 0 0 0-8 0v4Z"/>',keys:Array.from({length:9},(_,i)=>`<circle cx="${6+i%3*6}" cy="${6+Math.floor(i/3)*6}" r="1" fill="currentColor"/>`).join(''),star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',recent:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',contacts:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',voicemail:'<circle cx="6" cy="12" r="4"/><circle cx="18" cy="12" r="4"/><path d="M6 16h12"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'})[key]||''}</svg>`;
      if(nav.screen==='phone')body=`<section class="ps-phone-recents"><header class="ps-phone-top"><button type="button">编辑</button><button data-act="home" aria-label="返回桌面">主屏</button></header><h1>最近通话</h1><div class="ps-phone-segment"><button data-phone-filter="all" aria-pressed="true">全部</button><button data-phone-filter="missed" aria-pressed="false">未接</button></div><label class="ps-phone-search">${phoneSvg('search')}<input data-call-search placeholder="搜索" aria-label="搜索通话记录"></label><div class="ps-scroll">${rows().map(({record:x,history:h})=>`<div class="ps-recent-row" data-history-id="${E(h.id)}" data-call-name="${E((x.name+' '+x.number).toLowerCase())}" data-missed="${h.missed}"><button class="ps-recent-main" data-act="call-history" data-id="${E(h.id)}"><span><strong class="${h.missed?'missed':''}">${E(x.name||x.number)}</strong><small>${E(h.status||'手机')}</small></span><time>${E(historyTime(h,data.phone))}</time></button><button class="ps-recent-info" aria-label="${E(x.name)}的信息">${phoneSvg('info')}</button></div>`).join('')||'<div class="ps-empty">暂无通话</div>'}</div><nav class="ps-phone-tabs" aria-label="电话栏目">${[['star','个人收藏'],['recent','最近通话'],['contacts','通讯录'],['keys','拨号键盘'],['voicemail','语音留言']].map(([key,label])=>`<button type="button" ${key==='recent'?'aria-current="page"':''}>${phoneSvg(key)}<span>${label}</span></button>`).join('')}</nav></section>`;
      if(nav.screen==='call-detail'){const x=s.phone.records.find(x=>x.id===nav.id);if(x){if(!call)startCall(x);const line=(call.event?.lines??x.script)?.[call.index];body=`<section class="ps-call"><header><button class="ps-call-back" data-act="phone" aria-label="返回最近通话">${K.svg('arrow')}</button></header><div class="ps-call-identity">${avatar(x.name,x.avatar)}<h1>${E(x.name||x.number)}</h1><div data-call-status>${callStatus()}</div></div><div class="ps-call-story"><div data-call-bubble data-line-key="${line?E(line.id+':'+call.index):''}" ${line?'':'hidden'}>${line?`<small>${E(line.speaker)}</small><p>${E(line.text)}</p>`:''}</div></div><div class="ps-call-controls">${[['speaker','扬声器'],['video','FaceTime'],['mute','静音'],['add','添加通话'],['end','结束'],['keys','拨号键盘']].map(([key,label])=>`<button data-call-control data-act="${key==='end'?'call-end':'call-toggle'}" data-id="${key}" aria-label="${label}" aria-pressed="${call.lit.has(key)}" ${call.ended?'disabled':''}><span class="${key==='end'?'end':''}">${phoneSvg(key)}</span><small>${label}</small></button>`).join('')}</div></section>`;}else body=toolbar('最近通话','phone');}
      if(nav.screen==='browser')body=toolbar('浏览器','home')+`<div class="ps-scroll"><h1 class="ps-large-title">本地页面</h1>${s.browser.pages.map(x=>row(x.title,x.url,'web-page',x.id)).join('')}</div>`;
      if(nav.screen==='web-page'){const x=s.browser.pages.find(x=>x.id===nav.id);body=toolbar('阅读','browser')+`<div class="ps-scroll ps-rich"><small>${E(x?.url||'')}</small><h2>${E(x?.title||'页面已删除')}</h2><p>${E(x?.text||'')}</p></div>`;}
      if(nav.screen==='music')body=toolbar('音乐','home')+`<div class="ps-scroll">${s.music.tracks.map(x=>`<div class="ps-list-item">${x.cover?`<img src="${E(x.cover)}" alt="封面">`:''}<strong>${E(x.title)}</strong><p>${E(x.artist)}</p><button data-act="music-play" data-id="${E(x.id)}" ${!x.audio?'disabled':''}>${!x.audio?'未上传音频':trackId===x.id&&!player.paused?'暂停':'播放'}</button></div>`).join('')}<button class="ps-story-input" data-act="music-next">下一曲</button><p class="ps-section-meta" data-audio-status></p></div>`;
      if(nav.screen==='photos'){
        const groups=new Map(),dated=[...data.photos].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
        for(const p of dated){const key=p.date?(photoGroup==='year'?p.date.slice(0,4):photoGroup==='month'?p.date.slice(0,7):'all'):'undated';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);}
        const label=key=>key==='undated'?'未设置日期':key==='all'?'所有照片':key.length===4?key+'年':Number(key.slice(0,4))+'年'+Number(key.slice(5))+'月';
        body=`<section class="ps-gallery"><header class="ps-gallery-header"><button data-act="home">‹ 主屏</button></header><div class="ps-scroll"><h1 class="ps-large-title">图库</h1><p class="ps-section-meta">${data.photos.length} 张照片</p>${[...groups].map(([key,photos])=>`<section class="ps-photo-group"><h2>${E(label(key))}</h2><div class="ps-photo-grid">${photos.map(p=>`<button data-act="photo" data-id="${E(p.id)}" aria-label="查看 ${E(p.name)}"><img src="${E(p.src)}" alt="${E(p.name)}"></button>`).join('')}</div></section>`).join('')||'<div class="ps-empty">相册还是空的<br>上传照片，把回忆放进口袋</div>'}</div><nav class="ps-photo-switch" aria-label="图库视图">${[['year','年'],['month','月'],['all','所有照片']].map(([v,l])=>`<button data-act="photo-group" data-id="${v}" aria-pressed="${photoGroup===v}">${l}</button>`).join('')}</nav></section>`;
      }
      if(nav.screen==='photo'){const p=data.photos.find(x=>x.id===nav.id);if(p)body+=`<div class="ps-photo-caption">${E(p.date||'')} · ${E(p.location||'')} · ${E(p.tags||'')}</div>`;}
      if(nav.screen==='lock')body=body.replace('<div class="ps-notifications">','<div class="ps-notifications">'+Array.from(states.entries()).filter(([,st])=>st.unread).map(([id,st])=>{const c=data.contacts.find(c=>c.id===id);return `<div class="ps-notification" role="button" tabindex="0" data-act="unlock"><b>${E(c?.name||'消息')} · ${st.unread} 条未读</b><p>${E(c?viewMessages(c).at(-1)?.text||'':'')}</p></div>`;}).join(''));
      if(banner&&!['pin','lock','call-detail','redbook','redbook-detail','weibo','weibo-detail'].includes(nav.screen))body+=`<button class="ps-banner" data-act="story-notification"><b>${E(banner.title)}</b>${E(banner.text.slice(0,90))}</button>`;
